  const meta = isJsonObject(doc) && isJsonObject(doc["meta"]) ? doc["meta"] : {};
  const repository = isJsonObject(meta["repository"]) ? meta["repository"] : null;
  const name = pageOutput(run, doc);
  try {
    const out = join(runDir, name);
    assertWritable(root, out);
    const data = { title: (read.ok ? read.diagram.title : void 0) ?? run, doc, root: share ? null : root, project: share ? null : basename(root), repository };
    writeFileSync(out, renderPage(data, ASSETS));
  } catch (error) {
    return fail(`cannot write ${name}: ${error.message}`);
  }
